package io.github.diodeme.ji.artifact;

import java.util.Locale;

/** SHA-256 content identity in canonical sha256:&lt;lowercase hex&gt; form. */
public record ArtifactId(String value) {
    public ArtifactId {
        if (value == null || !value.matches("sha256:[0-9a-fA-F]{64}")) {
            throw new IllegalArgumentException("artifact id must be sha256 followed by 64 hex characters");
        }
        value = value.toLowerCase(Locale.ROOT);
    }

    public String hex() {
        return value.substring("sha256:".length());
    }
}
